"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisHowItWorksContent } from "./components/how-it-works/content";
import View4 from "./components/how-it-works/variants/05-card-deck";
const variants = {"card-deck":View4};
export type { ArtemisHowItWorksContent, ArtemisHowItWorksLink, ArtemisHowItWorksStep } from "./components/how-it-works/content";
export interface ArtemisHowItWorksProps { className?: string; variant?: "card-deck"; /** The words on the how-it-works section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHowItWorksContent>; }
export function ArtemisHowItWorks({ className, variant = "card-deck", content }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisHowItWorksLink {
  label: string;
  href: string;
}

/** One step of the process. Layouts number the steps in order and draw their own scene for each one. */
export interface ArtemisHowItWorksStep {
  /** A short label over the title, such as "Collect". All layouts. Keep labels unique, since story-stack and card-deck tell steps apart by it. */
  label: string;
  /** The step's title. All layouts. */
  title: string;
  /** A sentence or two under the title. All layouts; card-deck shows two lines of it. */
  description: string;
  /** The step's icon. centered-cards, process-grid, walkthrough and card-deck, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis how-it-works section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHowItWorksContent {
  /** The small pill over the headline. All layouts. */
  badge: string;
  /** The heading. All layouts; process-grid, story-stack, walkthrough and card-deck break it into two lines at the middle word. */
  headline: string;
  /** A line or two beside or under the headline. All layouts. */
  subhead: string;
  /** The button after the steps or beside the subhead. centered-cards, process-grid, story-stack and walkthrough. */
  cta?: ArtemisHowItWorksLink;
  /** The steps, in order. All layouts; three look best, and card-deck's own list has four. */
  steps: ArtemisHowItWorksStep[];
}

"use client";
// @zeus-internal
import { ArrowLeft, ArrowRight } from "lucide-react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisHowItWorksContent } from "../content";
import { defaultHeadline, defaultSteps } from "./05-card-deck/data";
import { DeckCard } from "./05-card-deck/deck-card";
const DEFAULT = {
    badge: "How it works",
    headline: defaultHeadline,
    subhead: "Move through the process one decision at a time. Use the controls to fold completed steps into the deck.",
    steps: defaultSteps,
} satisfies ArtemisHowItWorksContent;
const NAV_BUTTON_CLASS = "art:size-9 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9";
const DECK_CLASS = "art:relative art:mt-14 art:h-[25rem] art:w-full art:[--deck-card-width:calc(100cqw-6.5rem)] art:[--deck-gap:0.75rem] art:[--deck-stack-offset:1.5rem] art:@min-[640px]/artemis:mt-16 art:@min-[640px]/artemis:h-[27rem] art:@min-[640px]/artemis:[--deck-card-width:22rem] art:@min-[640px]/artemis:[--deck-gap:1rem] art:@min-[640px]/artemis:[--deck-stack-offset:3.5rem] art:@min-[1024px]/artemis:[--deck-card-width:28rem] art:@min-[1024px]/artemis:[--deck-stack-offset:4.75rem]";
const NAV_PRESS = { scale: 1 };
const INSTANT = { duration: 0 } as const;
const EYEBROW = {
    hidden: { opacity: 0, filter: "blur(5px)", transform: "translate3d(0,8px,0)" },
    shown: { opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0px,0)" },
};
const WORD = {
    hidden: { opacity: 0, filter: "blur(10px)", y: "22%" },
    shown: { opacity: 1, filter: "blur(0px)", y: "0%" },
};
const COPY = {
    hidden: { opacity: 0, filter: "blur(7px)", transform: "translate3d(0,12px,0)" },
    shown: { opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0px,0)" },
};
const DECK = {
    hidden: { opacity: 0, filter: "blur(8px)" },
    shown: { opacity: 1, filter: "blur(0px)" },
};
export default function HowItWorksCardDeck({ content }: { content?: Partial<ArtemisHowItWorksContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const words = copy.headline.split(" ");
    const lines = [words.slice(0, Math.floor(words.length / 2)), words.slice(Math.floor(words.length / 2))];
    const reduce = useReducedMotion();
    const headerRef = useRef<HTMLDivElement>(null);
    const deckRef = useRef<HTMLDivElement>(null);
    const headerInView = useInView(headerRef, { once: true, amount: 0.4 });
    const deckInView = useInView(deckRef, { once: true, amount: 0.15 });
    const [active, setActive] = useState(0);
    const last = copy.steps.length - 1;
    // With reduced motion everything shows at once, without waiting to be seen.
    const header = headerInView || reduce ? "shown" : "hidden";
    let wordIndex = 0;
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28" data-slot="how-it-works-card-deck">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div ref={headerRef} className="art:grid art:items-end art:gap-8 art:@min-[1024px]/artemis:grid-cols-[1fr_0.72fr] art:@min-[1024px]/artemis:gap-16">
          <div>
            <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" variants={EYEBROW} initial="hidden" animate={header} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
              {copy.badge}
            </motion.span>
            <h2 className="art:block art:mt-7 art:max-w-4xl art:text-balance art:tracking-[-0.05em] art:text-4xl art:font-medium">
              {lines.map((line) => (<span key={line.join(" ")} className="art:block">
                  {line.map((word, i) => {
                const order = wordIndex++;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" variants={WORD} initial="hidden" animate={header} transition={reduce ? INSTANT : { duration: 0.7, delay: order * 0.06, ease: ARTEMIS_EASE_OUT }}>
                        {word}
                        {i < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
                      </motion.span>);
            })}
                </span>))}
            </h2>
          </div>
          <motion.div className="art:max-w-xl art:@min-[1024px]/artemis:justify-self-end" variants={COPY} initial="hidden" animate={header} transition={reduce ? INSTANT : { duration: 0.55, delay: 0.22, ease: ARTEMIS_EASE_OUT }}>
            <p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              {copy.subhead}
            </p>
            <nav aria-label="Process navigation" className="art:mt-6 art:flex art:items-center art:gap-2">
              <ArtemisButton variant="tertiary" size="icon" className={NAV_BUTTON_CLASS} aria-label="Show previous process step" disabled={active === 0} whileTap={reduce ? undefined : NAV_PRESS} onClick={() => setActive((value) => Math.max(0, value - 1))}>
                <ArrowLeft className="art:size-4" aria-hidden="true"/>
              </ArtemisButton>
              <ArtemisButton variant="primary" size="icon" className={NAV_BUTTON_CLASS} aria-label="Stack the current process step" disabled={active === last} whileTap={reduce ? undefined : NAV_PRESS} onClick={() => setActive((value) => Math.min(last, value + 1))}>
                <ArrowRight className="art:size-4" aria-hidden="true"/>
              </ArtemisButton>
              <span aria-live="polite" className="art:sr-only">
                Step {active + 1} of {copy.steps.length}
              </span>
            </nav>
          </motion.div>
        </div>
        <motion.div ref={deckRef} className={DECK_CLASS} data-slot="how-it-works-card-deck-list" variants={DECK} initial="hidden" animate={deckInView || reduce ? "shown" : "hidden"} transition={reduce ? INSTANT : { duration: 0.65, delay: 0.12, ease: ARTEMIS_EASE_OUT }}>
          {copy.steps.map((step, index) => (<DeckCard key={step.label} step={step} index={index} active={active} total={copy.steps.length} onSelect={setActive}/>))}
        </motion.div>
      </div>
    </section>);
}

// @zeus-internal
import { Check, ClipboardList, FileCheckCorner, Layers, Send, Sparkles } from "lucide-react";
import type { ArtemisHowItWorksStep } from "../../content";
/** The steps the deck shows when it is given none. */
export const defaultSteps: ArtemisHowItWorksStep[] = [
    {
        label: "Collect",
        title: "Start with the real context",
        description: "Bring requests, notes, and examples into one place before deciding what the work should become.",
    },
    {
        label: "Shape",
        title: "Turn the signal into a brief",
        description: "Clarify the outcome, remove the noise, and give every decision a reason the whole team can see.",
    },
    {
        label: "Build",
        title: "Move through one shared plan",
        description: "Keep owners, progress, and review in the same flow so handoffs stay clear from start to finish.",
    },
    {
        label: "Release",
        title: "Ship the version everyone approved",
        description: "Close the loop with a final check, publish confidently, and leave the next iteration easy to find.",
    },
];
/** The art for each slot, in turn: the card's icon (kept when a step comes without one), the icon in its last tile, and its glow. */
export const ICONS = [ClipboardList, Sparkles, Layers, Send];
export const TILE_ICONS = [ClipboardList, Sparkles, FileCheckCorner, Check];
export const GLOWS = [
    "art:bg-[radial-gradient(circle_at_15%_0%,color-mix(in_oklab,var(--artemis-primary)_13%,transparent),transparent_58%)]",
    "art:bg-[radial-gradient(circle_at_82%_18%,color-mix(in_oklab,var(--artemis-primary)_11%,transparent),transparent_62%)]",
    "art:bg-[radial-gradient(circle_at_42%_100%,color-mix(in_oklab,var(--artemis-primary)_14%,transparent),transparent_60%)]",
    "art:bg-[radial-gradient(circle_at_100%_70%,color-mix(in_oklab,var(--artemis-primary)_12%,transparent),transparent_64%)]",
];
/** The headline the deck shows when it is given none; it breaks into two lines at the middle word. */
export const defaultHeadline = "A clear path from first thought to finished work.";
const STACKED = "var(--deck-stack-offset)";
const SLOT = "(var(--deck-card-width) + var(--deck-gap))";
export function deckTransform(index: number, active: number): string {
    const parts: string[] = [];
    for (let k = 0; k < index; k++)
        parts.push(k < active ? STACKED : SLOT);
    return `translate3d(${parts.length > 0 ? `calc(${parts.join(" + ")})` : "0px"}, 0, 0)`;
}
export function stepNumber(index: number): string {
    return String(index + 1).padStart(2, "0");
}

"use client";
// @zeus-internal
import { useReducedMotion } from "motion/react";
import type { ComponentType } from "react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT_CSS } from "../../../../lib/ease";
import type { ArtemisHowItWorksStep } from "../../content";
import { deckTransform, GLOWS, ICONS, stepNumber, TILE_ICONS } from "./data";
const CARD_CLASS = "art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:absolute art:inset-y-0 art:left-0 art:overflow-hidden art:border art:border-border/70 art:bg-background art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:transition-transform art:duration-700 art:motion-reduce:transition-none";
const TILE_CLASS = "art:flex art:items-center art:justify-center art:rounded-xl art:border art:border-border/70 art:bg-background/55 art:backdrop-blur-sm art:transition-[opacity,transform] art:duration-500 art:motion-reduce:transition-none";
const TILE_SIZES = ["art:size-14", "art:size-16", "art:size-20"] as const;
const CARD_PRESS = { scale: 0.99 };
export function DeckCard({ step, index, active, total, onSelect, }: {
    step: ArtemisHowItWorksStep;
    index: number;
    active: number;
    total: number;
    onSelect: (index: number) => void;
}) {
    const reduce = useReducedMotion();
    const current = index === active;
    const Icon: ComponentType<{ className?: string }> = step.icon ?? ICONS[index % ICONS.length];
    const TileIcon = TILE_ICONS[index % TILE_ICONS.length];
    const glow = GLOWS[index % GLOWS.length];
    return (<ArtemisButton variant="link" size="none" className={CARD_CLASS} aria-current={current ? "step" : undefined} data-slot="how-it-works-card-deck-card" whileTap={reduce ? undefined : CARD_PRESS} onClick={() => onSelect(index)} style={{
            transform: deckTransform(index, active),
            transitionTimingFunction: ARTEMIS_EASE_OUT_CSS,
            width: "var(--deck-card-width)",
            zIndex: index + 1,
        }}>
      <div aria-hidden="true" className={`art:absolute art:inset-0 art:transition-opacity art:duration-700 art:motion-reduce:transition-none ${glow} ${current ? "art:opacity-100" : "art:opacity-55"}`}/>
      <div className="art:relative art:flex art:h-full art:w-full art:flex-col art:p-5 art:@min-[640px]/artemis:p-6">
        <div className="art:flex art:items-center art:justify-between art:gap-4">
          <span className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">
            {stepNumber(index)} /{" "}
            {stepNumber(total - 1)}
          </span>
          <span className="art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:bg-muted art:text-muted-foreground art:rounded-full">
            <Icon className="art:size-4" aria-hidden="true"/>
          </span>
        </div>
        <div className="art:mt-auto">
          <div className="art:flex art:h-24 art:items-end art:gap-2" aria-hidden="true">
            {TILE_SIZES.map((size, t) => (<span key={size} className={`${TILE_CLASS} ${size} ${current ? "art:translate-y-0 art:opacity-100" : "art:translate-y-1 art:opacity-70"}`} style={{ transitionDelay: `${current ? t * 45 : 0}ms`, transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }}>
                {t < TILE_SIZES.length - 1 ? (<span className="art:h-px art:w-5 art:bg-border"/>) : (<TileIcon className="art:size-5 art:text-foreground" aria-hidden="true"/>)}
              </span>))}
          </div>
          <p className="art:mt-5 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{step.label}</p>
          <h3 className="art:mt-2 art:max-w-[20rem] art:text-pretty art:font-medium art:text-xl art:leading-tight art:tracking-[-0.025em]">{step.title}</h3>
          <p className="art:mt-3 art:max-w-[20rem] art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:line-clamp-2">
            {step.description}
          </p>
        </div>
      </div>
    </ArtemisButton>);
}
